@Override
    public void tick() {
        super.tick();
        SummonUtil.healOverTime(this);
        if (!level.isClientSide) {
            if (level.getGameTime() % 20 == 0 && !ownerLilyMap.containsValue(this.getUUID())) {
                this.remove(RemovalReason.DISCARDED);
            }
            if (wagTicks > 0 && isWagging()) {
                wagTicks--;
                if (wagTicks <= 0) {
                    setWagging(false);
                }
            }
        }
    }

@Override
    public void load(CompoundTag pCompound) {
        super.load(pCompound);
        if (!ownerLilyMap.containsKey(this.getOwnerUUID())) {
            Lily.ownerLilyMap.put(this.getOwnerUUID(), this.getUUID());
        }
    }

@Override
    public boolean onDispel(@NotNull LivingEntity caster) {
        if (caster.getUUID().equals(this.getOwnerUUID())) {
            this.remove(RemovalReason.DISCARDED);
            return true;
        }
        return false;
    }

@Override
    public void onServerReceived(MinecraftServer minecraftServer, ServerPlayer player) {
        if (dogType == DogType.NOOK) {
            Nook nook = new Nook(player.level);
            nook.setPos(player.getX(), player.getY(), player.getZ());
            nook.setOwnerUUID(player.getUUID());
            player.level.addFreshEntity(nook);
            Nook.ownerNookMap.put(player.getUUID(), nook.getUUID());
        } else {
            Lily lily = new Lily(player.level);
            lily.setPos(player.getX(), player.getY(), player.getZ());
            lily.setOwnerUUID(player.getUUID());
            player.level.addFreshEntity(lily);
            Lily.ownerLilyMap.put(player.getUUID(), lily.getUUID());
        }
    }

@Override
    public void onServerReceived(MinecraftServer minecraftServer, ServerPlayer player) {
        if (dogType == PacketSummonDog.DogType.NOOK) {
            ServerLevel level = (ServerLevel) player.level();
            UUID nookUuid = Nook.ownerNookMap.get(player.getUUID());
            if (nookUuid != null) {
                Nook nook = (Nook) level.getEntity(nookUuid);
                if (nook != null) {
                    nook.remove(Entity.RemovalReason.DISCARDED);
                }
            }
        } else {
            ServerLevel level = (ServerLevel) player.level();
            UUID lilyUuid = Lily.ownerLilyMap.get(player.getUUID());
            if (lilyUuid != null) {
                Lily lily = (Lily) level.getEntity(lilyUuid);
                if (lily != null) {
                    lily.remove(Entity.RemovalReason.DISCARDED);
                }
            }
        }
    }

public static <T extends AbstractPacket> void handle(T message, IPayloadContext ctx) {
        if (ctx.flow().getReceptionSide() == LogicalSide.SERVER) {
            handleServer(message, ctx);
        } else {
            //separate class to avoid loading client code on server.
            //Using OnlyIn on a method in this class would work too, but is discouraged
            ClientMessageHandler.handleClient(message, ctx);
        }
    }

private static <T extends AbstractPacket> void handleServer(T message, IPayloadContext ctx) {
        MinecraftServer server = ctx.player().getServer();
        message.onServerReceived(server, (ServerPlayer) ctx.player());
    }

